// The only file in this package that DECLARES anything. The authoritative
// target for every `fixture-lib` rule below lives here, not in the facade.

function vulnerable(input) {
  return "vulnerable:" + input;
}

function safe(input) {
  return "safe:" + input;
}

// Published, cleanly attributed, and called by nothing in this fixture --
// the valid Family C control's target.
function unused(input) {
  return "unused:" + input;
}

// The value the facade GENUINELY reassigns `rebound` to before exporting
// it. `fixture-lib#rebound` is therefore not this file's `reboundOriginal`
// at runtime, which is why attribution must stay refused for it.
function reboundOriginal(input) {
  return "rebound-original:" + input;
}

function reboundReplacement(input) {
  return "rebound-replacement:" + input;
}

exports.vulnerable = vulnerable;
exports.safe = safe;
exports.unused = unused;
exports.reboundOriginal = reboundOriginal;
exports.reboundReplacement = reboundReplacement;
